package org.slavicmyths.finist;
import net.minecraft.commands.Commands;import net.minecraft.server.level.ServerLevel;import net.minecraft.server.level.ServerPlayer;import net.minecraft.world.entity.*;import net.minecraft.world.entity.monster.Monster;import net.minecraft.world.entity.ai.goal.Goal;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.neoforge.event.*;import net.neoforged.neoforge.event.entity.*;import net.neoforged.neoforge.event.entity.living.*;import org.slavicmyths.skim.HeroCalls;
@EventBusSubscriber(modid="slavicmyths")
public final class FinistEvents {
 @SubscribeEvent public static void tick(net.neoforged.neoforge.event.tick.ServerTickEvent.Post e){KartausEncounter.get(e.getServer().overworld()).tick(e.getServer().overworld());}
 @SubscribeEvent public static void commands(RegisterCommandsEvent e){e.getDispatcher().register(Commands.literal("slavicmyths").then(Commands.literal("hero").then(Commands.literal("finist").executes(c->HeroCalls.toggle(c.getSource().getPlayerOrException(),"finist")?1:0))).then(Commands.literal("kartaus").then(Commands.literal("challenge").executes(c->KartausEncounter.start(c.getSource().getPlayerOrException())?1:0))));}
 @SubscribeEvent public static void incoming(LivingIncomingDamageEvent e){if(e.getEntity() instanceof FinistEntity f&&f.evade(e.getSource())){e.setCanceled(true);return;}if(e.getEntity() instanceof ServerPlayer p&&p.level() instanceof ServerLevel){var h=HeroCalls.loaded(p,"finist");if(h instanceof FinistEntity f&&f.level()==p.level()&&f.guard(e.getSource(),p)){e.setCanceled(true);return;}}
 if(e.getSource().getEntity() instanceof Monster m&&m.getPersistentData().hasUUID("KartausBoss174")&&m.level() instanceof ServerLevel w){var k=w.getEntity(m.getPersistentData().getUUID("KartausBoss174"));if(!(k instanceof KartausEntity b)||e.getEntity()!=b.getTarget()&&e.getEntity()!=b.hero())e.setCanceled(true);}}
 @SubscribeEvent public static void damage(LivingDamageEvent.Pre e){float d=e.getNewDamage();if(e.getEntity() instanceof KartausEntity k)d*=1-k.mitigation();if(e.getSource().getDirectEntity() instanceof ServerPlayer p&&e.getSource().getEntity()==p){var h=HeroCalls.loaded(p,"finist");if(h instanceof FinistEntity f&&f.level()==p.level()&&f.boosts(p,e.getEntity()))d*=1.15F;}
 if(e.getEntity() instanceof FinistEntity f&&!f.lethalUsed&&d>=f.getHealth()&&!e.getSource().is(net.minecraft.world.damagesource.DamageTypes.GENERIC_KILL)){f.lethalUsed=true;d=Math.max(0,f.getHealth()-1);f.retreat();}e.setNewDamage(d);}
 @SubscribeEvent public static void after(LivingDamageEvent.Post e){if(e.getEntity() instanceof KartausEntity k&&e.getNewDamage()>0)k.ownerDamage(e.getSource());}
 @SubscribeEvent public static void join(EntityJoinLevelEvent e){if(e.getLevel().isClientSide||!(e.getEntity() instanceof Monster m)||!m.getPersistentData().hasUUID("KartausBoss174"))return;m.targetSelector.removeAllGoals(g->true);m.goalSelector.addGoal(0,new GuardGoal(m));}
 private static final class GuardGoal extends Goal{private final Monster m;GuardGoal(Monster m){this.m=m;}@Override public boolean canUse(){return true;}@Override public boolean requiresUpdateEveryTick(){return false;}@Override public void tick(){if(m.tickCount%10!=0||!(m.level() instanceof ServerLevel w))return;var id=m.getPersistentData().getUUID("KartausBoss174");var e=w.getEntity(id);if(!(e instanceof KartausEntity b)||!b.isAlive()||!b.validEncounter()||!b.guards.contains(m.getUUID())){m.discard();return;}m.setTarget(b.getTarget());if(m.getPersistentData().getLong("FinistDistractedUntil")>w.getGameTime())m.setTarget(null);}}
 @SubscribeEvent public static void drops(LivingDropsEvent e){if(e.getEntity().getPersistentData().hasUUID("KartausBoss174")||e.getEntity() instanceof KartausEntity||e.getEntity() instanceof BannerEntity)e.setCanceled(true);}
 @SubscribeEvent public static void xp(LivingExperienceDropEvent e){if(e.getEntity().getPersistentData().hasUUID("KartausBoss174")||e.getEntity() instanceof KartausEntity||e.getEntity() instanceof BannerEntity)e.setDroppedExperience(0);}
}
